  Lemma blk_apart : forall b, ablock_range H (blk_addr b) (blk_size b) ->
    blk_addr b + blk_size b <= xS1 e - 8192
    /\ (blk_addr b + blk_size b <= ff \/ ff + 2048 <= blk_addr b)
    /\ (blk_addr b + blk_size b <= sh ff \/ sh ff + 256 <= blk_addr b)
    /\ sh (blk_addr b) + nsh (blk_size b) <= xS1 e - 8192
    /\ (sh (blk_addr b) + nsh (blk_size b) <= ff \/ ff + 2048 <= sh (blk_addr b))
    /\ (sh (blk_addr b) + nsh (blk_size b) <= sh ff \/ sh ff + 256 <= sh (blk_addr b)).
Proof.
